def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_rate = opp_c / n
    my_last, opp_last = history[-1]
    if n < 8:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'
    window = min(12, n)
    recent = history[-window:]
    rec_opp_c = sum(1 for a, b in recent if b == 'C')
    rec_rate = rec_opp_c / window
    if n >= 92:
        if opp_rate >= 0.75:
            return 'D'
        if rec_rate >= 0.8:
            return 'D'
        return 'C'
    if n >= 84:
        if opp_rate >= 0.85 and rng.random() < 0.6:
            return 'D'
        if rec_rate >= 0.9:
            return 'C'
    if rec_rate >= 0.92:
        if rng.random() < 0.06:
            return 'D'
        return 'C'
    if rec_rate <= 0.2:
        if rng.random() < 0.05:
            return 'C'
        return 'D'
    if opp_last == 'D':
        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            return 'D'
        if my_last == 'D':
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        return 'D'
    if opp_last == 'C':
        if my_last == 'D':
            if rec_rate >= 0.6:
                return 'C'
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if rec_rate >= 0.6:
            return 'C'
        if rng.random() < 0.75:
            return 'C'
        return 'D'
    return 'C'
